def calculate_simple_gpa(university, student_id):
    '''
    Calculate cumulative GPA for a student using university and student_id.

    Approach (Chain of Thought):
    1. Get enrollments for the student using university.get_student_enrollments(student_id)
    2. For each enrollment:
        a. Retrieve the course object using university.get_course(enrollment.course_code)
        b. Get grade points from enrollment.get_grade_points()
        c. Multiply grade points by course.credits to get total points for this course
    3. Sum all the (grade points * credits) to get total_points
    4. Sum all credits attempted to get total_credits
    5. If total_credits > 0, return total_points / total_credits as GPA (rounded to 3 decimals)
       Otherwise, return 0.0
    '''
    total_points = 0.0
    total_credits = 0

    enrollments = university.get_student_enrollments(student_id)
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course:
            grade_points = enrollment.get_grade_points()
            credits = course.credits

            total_points += grade_points * credits
            total_credits += credits

    if total_credits > 0:
        return total_points / total_credits
    else:
        return 0.0


# Test cases for calculate_simple_gpa

# Mocks for University, Enrollment, and Course objects
class Course:
    def __init__(self, code, credits):
        self.code = code
        self.credits = credits

class Enrollment:
    def __init__(self, course_code, grade_points):
        self.course_code = course_code
        self._grade_points = grade_points
    def get_grade_points(self):
        return self._grade_points

class University:
    def __init__(self, enrollments_by_student, courses_by_code):
        self.enrollments_by_student = enrollments_by_student
        self.courses_by_code = courses_by_code
    def get_student_enrollments(self, student_id):
        return self.enrollments_by_student.get(student_id, [])
    def get_course(self, course_code):
        return self.courses_by_code[course_code]

def calculate_simple_gpa(university, student_id):
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0.0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        points = enrollment.get_grade_points() * course.credits
        total_points += points
        total_credits += course.credits
    return (total_points / total_credits) if total_credits > 0 else 0.0

