        Enrollment('PHYS101', 4.0),
    ]
}
university = University(enrollments, courses)
assert calculate_simple_gpa(university, 'stu2') == 4.0, "All A's results in 4.0 GPA"

# Test case 3: All F (0.0) GPAs
courses = {
    'ENG101': Course('ENG101', 3),
